    43→
    44→// Helper: Extraire l'ID YouTube depuis une URL
    45→function extractYouTubeID(input: string): string | null {
    46→  if (/^[a-zA-Z0-9_-]{11}$/.test(input.trim())) {
    47→    return input.trim();
    48→  }
    49→
    50→  const patterns = [
    51→    /(?:youtube\.com\/watch\?v=|youtu\.be\/)([a-zA-Z0-9_-]{11})/,
    52→    /youtube\.com\/embed\/([a-zA-Z0-9_-]{11})/,
    53→    /youtube\.com\/v\/([a-zA-Z0-9_-]{11})/,
    54→  ];
    55→
    56→  for (const pattern of patterns) {
    57→    const match = input.match(pattern);
