import { createCanvas, loadImage } from 'canvas';
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));

// Tailles pour le fichier ICO
const sizes = [16, 32, 48];

// Créer le PNG manuellement depuis le design du SVG
function createFaviconPNG(size) {
  const canvas = createCanvas(size, size);
  const ctx = canvas.getContext('2d');

  const scale = size / 64;

  // Rectangle jaune (fond décalé)
  ctx.fillStyle = '#D5FF0A';
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 2 * scale;
  ctx.fillRect(4 * scale, 4 * scale, 56 * scale, 56 * scale);
  ctx.strokeRect(4 * scale, 4 * scale, 56 * scale, 56 * scale);

  // Rectangle blanc (premier plan)
  ctx.fillStyle = 'white';
  ctx.fillRect(0, 0, 56 * scale, 56 * scale);
  ctx.strokeRect(0, 0, 56 * scale, 56 * scale);

  // Texte "LG"
  ctx.fillStyle = 'black';
  ctx.font = `900 ${24 * scale}px sans-serif`;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('LG', 28 * scale, 30 * scale);

  return canvas.toBuffer('image/png');
}

// Fonction pour créer un fichier ICO simple
function createICO(pngBuffers) {
  // Structure ICO header
  const numImages = pngBuffers.length;
  const headerSize = 6;
  const dirEntrySize = 16;

  // Calculer la taille totale
  let dataOffset = headerSize + (dirEntrySize * numImages);
  const imageOffsets = [];

  for (const buffer of pngBuffers) {
    imageOffsets.push(dataOffset);
    dataOffset += buffer.length;
  }

  // Créer le buffer final
  const totalSize = dataOffset;
  const icoBuffer = Buffer.alloc(totalSize);

  // ICO Header
  icoBuffer.writeUInt16LE(0, 0);       // Reserved
  icoBuffer.writeUInt16LE(1, 2);       // Type (1 = ICO)
  icoBuffer.writeUInt16LE(numImages, 4); // Number of images

  // Directory entries
  let offset = headerSize;
  for (let i = 0; i < numImages; i++) {
    const size = sizes[i];
    const pngBuffer = pngBuffers[i];

    icoBuffer.writeUInt8(size === 256 ? 0 : size, offset);     // Width
    icoBuffer.writeUInt8(size === 256 ? 0 : size, offset + 1); // Height
    icoBuffer.writeUInt8(0, offset + 2);                        // Color palette
    icoBuffer.writeUInt8(0, offset + 3);                        // Reserved
    icoBuffer.writeUInt16LE(1, offset + 4);                     // Color planes
    icoBuffer.writeUInt16LE(32, offset + 6);                    // Bits per pixel
    icoBuffer.writeUInt32LE(pngBuffer.length, offset + 8);      // Size of image data
    icoBuffer.writeUInt32LE(imageOffsets[i], offset + 12);      // Offset to image data

    offset += dirEntrySize;
  }

  // Image data
  for (let i = 0; i < numImages; i++) {
    pngBuffers[i].copy(icoBuffer, imageOffsets[i]);
  }

  return icoBuffer;
}

